// Some portions generated by Codex
package org.eclipse.rdf4j.sail.lmdb;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

import org.junit.jupiter.api.Test;

/**
 * Group-canonical OUTPUT_ROWS learning keys: the packed cost session keys every alternative of one logical memo group
 * (Difference, correlated NOT-EXISTS filter, typed anti-join over the same MINUS) by the canonical member's operator
 * family and structural-topology hex. Per-alternative keying let the executed framing accumulate corrections while its
 * never-executed siblings kept raw estimates, flipping near-tied plans (MEDICAL q9 oscillation, 2026-08-04).
 */
class FrontierLearningKeyGroupFamilyTest {

	// The three physical framings of one MINUS group as the session builds them after A1: same canonical family
	// and topology hex, distinct Frontier operations and access kernels.
	private static final FrontierLearningKey DIFFERENCE = FrontierLearningKey.of(
			"difference", "DIFFERENCE@1fad0aa0", 17L, 0L, "difference", "none", "none");
	private static final FrontierLearningKey NOT_EXISTS_FILTER = FrontierLearningKey.of(
			"difference", "BOUNDARY@1fad0aa0", 31L, 5L, "semi-anti:memoized", "spoc", "directLookup");
	private static final FrontierLearningKey ANTI_JOIN = FrontierLearningKey.of(
			"difference", "ANTI_JOIN@1fad0aa0", 31L, 5L, "semi-anti:materialized", "posc", "prefixScan");
	private static final FrontierLearningKey UNRELATED_GROUP = FrontierLearningKey.of(
			"difference", "DIFFERENCE@2df90bb0", 17L, 0L, "difference", "none", "none");
	private static final FrontierLearningKey INCOMPATIBLE_APPLICABILITY = FrontierLearningKey.of(
			"difference", "ANTI_JOIN@1fad0aa0", 91L, 73L, "semi-anti:materialized", "posc", "prefixScan");

	@Test
	void outputRowsFamilyCollapsesAcrossGroupAlternatives() {
		assertEquals(DIFFERENCE.familyKey(FrontierCostDimension.OUTPUT_ROWS),
				NOT_EXISTS_FILTER.familyKey(FrontierCostDimension.OUTPUT_ROWS),
				"Output cardinality is a property of the logical relation, not the framing that executed");
		assertEquals(DIFFERENCE.familyKey(FrontierCostDimension.OUTPUT_ROWS),
				ANTI_JOIN.familyKey(FrontierCostDimension.OUTPUT_ROWS),
				"Every alternative in the group must share one OUTPUT_ROWS learning family");
		assertNotEquals(DIFFERENCE.familyKey(FrontierCostDimension.OUTPUT_ROWS),
				UNRELATED_GROUP.familyKey(FrontierCostDimension.OUTPUT_ROWS),
				"Distinct logical groups keep distinct cardinality families");
		assertNotEquals(NOT_EXISTS_FILTER.familyKey(FrontierCostDimension.SOURCE_ROWS_SCANNED),
				ANTI_JOIN.familyKey(FrontierCostDimension.SOURCE_ROWS_SCANNED),
				"Physical-dimension families retain the alternative's access identity");
		assertNotEquals(DIFFERENCE.familyKey(FrontierCostDimension.EXPRESSION_EVALUATIONS),
				NOT_EXISTS_FILTER.familyKey(FrontierCostDimension.EXPRESSION_EVALUATIONS),
				"Scan/seek/hash evidence must not pool across kernels");
	}

	@Test
	void topologyFamilyCardinalityIsDiagnosticOnly() {
		FrontierLearningModel model = new FrontierLearningModel();
		model.observe(DIFFERENCE, FrontierCostDimension.OUTPUT_ROWS, 100.0d, 400.0d, 1L);

		assertTrue(model.correct(ANTI_JOIN, FrontierCostDimension.OUTPUT_ROWS, 100.0d, false).isEmpty(),
				"Topology-family evidence is diagnostic and cannot move an unobserved alternative");
		assertTrue(model.correct(UNRELATED_GROUP, FrontierCostDimension.OUTPUT_ROWS, 100.0d, false).isEmpty(),
				"Another group's MINUS shares nothing");
		assertTrue(model.correct(ANTI_JOIN, FrontierCostDimension.SOURCE_ROWS_SCANNED, 100.0d, false).isEmpty(),
				"Pooling is cardinality-only — no physical actuals were observed for the anti-join kernel");
	}

	@Test
	void outputRowsEvidenceDoesNotCrossIncompatibleApplicability() {
		FrontierLearningModel model = new FrontierLearningModel();
		model.observe(DIFFERENCE, FrontierCostDimension.OUTPUT_ROWS, 100.0d, 400.0d, 1L);

		assertTrue(model.correct(INCOMPATIBLE_APPLICABILITY, FrontierCostDimension.OUTPUT_ROWS, 100.0d, false)
				.isEmpty(),
				"A shared topology digest must not leak cardinality evidence across binding and correlation contracts");
	}
}
